def save_task_request(self, idents, msg):
        """Save the submission of a task."""
        client_id = idents[0]

        try:
            msg = self.session.unserialize(msg)
        except Exception:
            self.log.error("task::client %r sent invalid task message: %r",
                    client_id, msg, exc_info=True)
            return
        record = init_record(msg)

        record['client_uuid'] = client_id.decode('ascii')
        record['queue'] = 'task'
        header = msg['header']
        msg_id = header['msg_id']
        self.pending.add(msg_id)
        self.unassigned.add(msg_id)
        try:
            # it's posible iopub arrived first:
            existing = self.db.get_record(msg_id)
            if existing['resubmitted']:
                for key in ('submitted', 'client_uuid', 'buffers'):
                    # don't clobber these keys on resubmit
                    # submitted and client_uuid should be different
                    # and buffers might be big, and shouldn't have changed
                    record.pop(key)
                    # still check content,header which should not change
                    # but are not expensive to compare as buffers

            for key,evalue in existing.iteritems():
                if key.endswith('buffers'):
                    # don't compare buffers
                    continue
                rvalue = record.get(key, None)
                if evalue and rvalue and evalue != rvalue:
                    self.log.warn("conflicting initial state for record: %r:%r <%r> %r", msg_id, rvalue, key, evalue)
                elif evalue and not rvalue:
                    record[key] = evalue
            try:
                self.db.update_record(msg_id, record)
            except Exception:
                self.log.error("DB Error updating record %r", msg_id, exc_info=True)
        except KeyError:
            try:
                self.db.add_record(msg_id, record)
            except Exception:
                self.log.error("DB Error adding record %r", msg_id, exc_info=True)
        except Exception:
            self.log.error("DB Error saving task request %r", msg_id, exc_info=True)

def terminal(self, text):
    """terminal = '"' . (printable - '"') + . '"'
                | "'" . (printable - "'") + . "'" ;
    """
    self._attempting(text)
    return alternation([
      concatenation([
        '"',
        one_or_more(
          exclusion(self.printable, '"')
        ),
        '"'
      ], ignore_whitespace=False),
      concatenation([
        "'",
        one_or_more(
          exclusion(self.printable,"'")
        ),
        "'"
      ], ignore_whitespace=False)
    ])(text).compressed(TokenType.terminal)

def find_last(fileobj, serial):
        """Find the last page of the stream 'serial'.

        If the file is not multiplexed this function is fast. If it is,
        it must read the whole the stream.

        This finds the last page in the actual file object, or the last
        page in the stream (with eos set), whichever comes first.
        """

        # For non-muxed streams, look at the last page.
        try:
            fileobj.seek(-256*256, 2)
        except IOError:
            # The file is less than 64k in length.
            fileobj.seek(0)
        data = fileobj.read()
        try:
            index = data.rindex(b"OggS")
        except ValueError:
            raise error("unable to find final Ogg header")
        bytesobj = cBytesIO(data[index:])
        best_page = None
        try:
            page = OggPage(bytesobj)
        except error:
            pass
        else:
            if page.serial == serial:
                if page.last:
                    return page
                else:
                    best_page = page
            else:
                best_page = None

        # The stream is muxed, so use the slow way.
        fileobj.seek(0)
        try:
            page = OggPage(fileobj)
            while not page.last:
                page = OggPage(fileobj)
                while page.serial != serial:
                    page = OggPage(fileobj)
                best_page = page
            return page
        except error:
            return best_page
        except EOFError:
            return best_page

def get_ip_packet(data, client_port, server_port, is_loopback=False):
    """ if client_port is 0 any client_port is good """
    header = _loopback if is_loopback else _ethernet

    try:
        header.unpack(data)
    except Exception as ex:
        raise ValueError('Bad header: %s' % ex)

    tcp_p = getattr(header.data, 'data', None)
    if type(tcp_p) != dpkt.tcp.TCP:
        raise ValueError('Not a TCP packet')

    if tcp_p.dport == server_port:
        if client_port != 0 and tcp_p.sport != client_port:
            raise ValueError('Request from different client')
    elif tcp_p.sport == server_port:
        if client_port != 0 and tcp_p.dport != client_port:
            raise ValueError('Reply for different client')
    else:
        raise ValueError('Packet not for/from client/server')

    return header.data

