                "-i", OPJ(self.workdir, self.name+".treemix.in.gz"),
                "-o", OPJ(self.workdir, self.name),
                ]

        ## addon params
        args = []
        for key, val in self.params:
            if key not in ["minmap", "binary"]:
                if key == "g":
                    if val[0]:
                        args += ["-"+key, str(val[0]), str(val[1])]
                elif key == "global_":
                    if val:
