def hard_Pk(k,R,SNR,M=2):
    """
    Pk = hard_Pk(k,R,SNR)
    
    Calculates Pk as found in Ziemer & Peterson eq. 7-12, p.505
    
    Mark Wickert and Andrew Smit 2018
    """

    k = int(k)

    if M == 2:
        p = Q_fctn(np.sqrt(2.*R*SNR))
    else:
        p = 4./np.log2(M)*(1 - 1./np.sqrt(M))*\
            Q_fctn(np.sqrt(3*R*np.log2(M)/float(M-1)*SNR))
    Pk = 0
    #if 2*k//2 == k:
    if np.mod(k,2) == 0:
        for e in range(int(k/2+1),int(k+1)):
            Pk += float(factorial(k))/(factorial(e)*factorial(k-e))*p**e*(1-p)**(k-e);
        # Pk += 1./2*float(factorial(k))/(factorial(int(k/2))*factorial(int(k-k/2)))*\
        #       p**(k/2)*(1-p)**(k//2);
        Pk += 1./2*float(factorial(k))/(factorial(int(k/2))*factorial(int(k-k/2)))*\
            p**(k/2)*(1-p)**(k/2);
    elif np.mod(k,2) == 1:
        for e in range(int((k+1)//2),int(k+1)):
            Pk += factorial(k)/(factorial(e)*factorial(k-e))*p**e*(1-p)**(k-e);
    return Pk

def download_vault_folder(remote_path, local_path, dry_run=False, force=False):
    """Recursively downloads a folder in a vault to a local directory.
    Only downloads files, not datasets."""

    local_path = os.path.normpath(os.path.expanduser(local_path))
    if not os.access(local_path, os.W_OK):
        raise Exception(
            'Write access to local path ({}) is required'
            .format(local_path))

    full_path, path_dict = solvebio.Object.validate_full_path(remote_path)
    vault = solvebio.Vault.get_by_full_path(path_dict['vault'])
    print('Downloading all files from {} to {}'.format(full_path, local_path))

    if path_dict['path'] == '/':
        parent_object_id = None
    else:
        parent_object = solvebio.Object.get_by_full_path(
            remote_path, assert_type='folder')
        parent_object_id = parent_object.id

    # Scan the folder for all sub-folders and create them locally
    print('Creating local directory structure at: {}'.format(local_path))
    if not os.path.exists(local_path):
        if not dry_run:
            os.makedirs(local_path)

    folders = vault.folders(parent_object_id=parent_object_id)
    for f in folders:
        path = os.path.normpath(local_path + f.path)
        if not os.path.exists(path):
            print('Creating folder: {}'.format(path))
            if not dry_run:
                os.makedirs(path)

    files = vault.files(parent_object_id=parent_object_id)
    for f in files:
        path = os.path.normpath(local_path + f.path)
        if os.path.exists(path):
            if force:
                # Delete the local copy
                print('Deleting local file (force download): {}'.format(path))
                if not dry_run:
                    os.remove(path)
            else:
                print('Skipping file (already exists): {}'.format(path))
                continue

        print('Downloading file: {}'.format(path))
        if not dry_run:
            f.download(path)

def GetTopLevelControl(self) -> 'Control':
        """
        Get the top level control which current control lays.
        If current control is top level, return self.
        If current control is root control, return None.
        Return `PaneControl` or `WindowControl` or None.
        """
        handle = self.NativeWindowHandle
        if handle:
            topHandle = GetAncestor(handle, GAFlag.Root)
            if topHandle:
                if topHandle == handle:
                    return self
                else:
                    return ControlFromHandle(topHandle)
            else:
                #self is root control
                pass
        else:
            control = self
            while True:
                control = control.GetParentControl()
                handle = control.NativeWindowHandle
                if handle:
                    topHandle = GetAncestor(handle, GAFlag.Root)
                    return ControlFromHandle(topHandle)

def _real_time_thread(self):
    """Handles real-time updates to the order book."""
    while self.ws_client.connected():
      if self.die:
        break

      if self.pause:
        sleep(5)
        continue

      message = self.ws_client.receive()

      if message is None:
        break

      message_type = message['type']

      if message_type  == 'error':
        continue
      if message['sequence'] <= self.sequence:
        continue

      if message_type == 'open':
        self._handle_open(message)
      elif message_type == 'match':
        self._handle_match(message)
      elif message_type == 'done':
        self._handle_done(message)
      elif message_type == 'change':
        self._handle_change(message)
      else:
        continue

    self.ws_client.disconnect()

