def getBucketIndices(self, input):
    """ See method description in base.py """

    if input == SENTINEL_VALUE_FOR_MISSING_DATA:
      # Encoder each sub-field
      return [None] * len(self.encoders)

    else:
      assert isinstance(input, datetime.datetime)

      # Get the scalar values for each sub-field
      scalars = self.getScalars(input)

      # Encoder each sub-field
      result = []
      for i in xrange(len(self.encoders)):
        (name, encoder, offset) = self.encoders[i]
        result.extend(encoder.getBucketIndices(scalars[i]))
      return result

def distrib_id():
    """
    Get the OS distribution ID.

    Example::

        from burlap.system import distrib_id

        if distrib_id() != 'Debian':
            abort(u"Distribution is not supported")

    """

    with settings(hide('running', 'stdout')):
        kernel = (run('uname -s') or '').strip().lower()
        if kernel == LINUX:
            # lsb_release works on Ubuntu and Debian >= 6.0
            # but is not always included in other distros
            if is_file('/usr/bin/lsb_release'):
                id_ = run('lsb_release --id --short').strip().lower()
                if id in ['arch', 'archlinux']:  # old IDs used before lsb-release 1.4-14
                    id_ = ARCH
                return id_
            else:
                if is_file('/etc/debian_version'):
                    return DEBIAN
                elif is_file('/etc/fedora-release'):
                    return FEDORA
                elif is_file('/etc/arch-release'):
                    return ARCH
                elif is_file('/etc/redhat-release'):
                    release = run('cat /etc/redhat-release')
                    if release.startswith('Red Hat Enterprise Linux'):
                        return REDHAT
                    elif release.startswith('CentOS'):
                        return CENTOS
                    elif release.startswith('Scientific Linux'):
                        return SLES
                elif is_file('/etc/gentoo-release'):
                    return GENTOO
        elif kernel == SUNOS:
            return SUNOS

def _loadDeclarations(self):
        """
        load declaratoins from _declr method
        This function is called first for parent and then for children
        """
        if not hasattr(self, "_interfaces"):
            self._interfaces = []
        self._setAttrListener = self._declrCollector
        self._declr()
        self._setAttrListener = None

        for i in self._interfaces:
            i._isExtern = self._isExtern
            i._loadDeclarations()

        for p in self._params:
            p.setReadOnly()

        if self._isExtern:
            # direction from inside of unit (reverset compared to outside direction)
            if self._direction == INTF_DIRECTION.UNKNOWN:
                self._direction = INTF_DIRECTION.MASTER
            self._setDirectionsLikeIn(self._direction)

