def _build_expr(tokens, higher_oplevel=-1, ldelim="(", rdelim=")"):
    """Build mathematical expression from hierarchical list."""
    # Numbers
    if isinstance(tokens, str):
        return tokens
    # Unary operators
    if len(tokens) == 2:
        return "".join(tokens)
    # Multi-term operators
    oplevel = _get_op_level(tokens[1])
    stoken = ""
    for num, item in enumerate(tokens):
        if num % 2 == 0:
            stoken += _build_expr(item, oplevel, ldelim=ldelim, rdelim=rdelim)
        else:
            stoken += item
    if (oplevel < higher_oplevel) or (
        (oplevel == higher_oplevel) and (oplevel in _OP_PREC_PAR)
    ):
        stoken = ldelim + stoken + rdelim
    return stoken

def _check_and_save_parm(self, parms, parameter_name, parameter_value):
        """
        If a parameter is not stored in parms dict save it there (even though the value is None).
        Else check if the parameter has been already set during initialization of estimator. If yes, check the new value is the same or not. If the values are different, set the last passed value to params dict and throw UserWarning.
        """
        if parameter_name not in parms:
            parms[parameter_name] = parameter_value
        elif parameter_value is not None and parms[parameter_name] != parameter_value:
            parms[parameter_name] = parameter_value
            warnings.warn("\n\n\t`%s` parameter has been already set and had a different value in `train` method. The last passed value \"%s\" is used." % (parameter_name, parameter_value), UserWarning, stacklevel=2)

def intercom_user_hash(data):
    """
    Return a SHA-256 HMAC `user_hash` as expected by Intercom, if configured.

    Return None if the `INTERCOM_HMAC_SECRET_KEY` setting is not configured.
    """
    if getattr(settings, 'INTERCOM_HMAC_SECRET_KEY', None):
        return hmac.new(
            key=_hashable_bytes(settings.INTERCOM_HMAC_SECRET_KEY),
            msg=_hashable_bytes(data),
            digestmod=hashlib.sha256,
        ).hexdigest()
    else:
        return None

def suffixes(self):
        """The registry for supported suffixes of assets. It is built from
        MIME types and compilers registries, and is cached at the first call.
        See :class:`~gears.environment.Suffixes` for more information.
        """
        if not hasattr(self, '_suffixes'):
            suffixes = Suffixes()
            for extension, mimetype in self.mimetypes.items():
                suffixes.register(extension, root=True, mimetype=mimetype)
            for extension, compiler in self.compilers.items():
                suffixes.register(extension, to=compiler.result_mimetype)
            self._suffixes = suffixes
        return self._suffixes

