def _get_image_from_file(dir_path, image_file):
    """
    Get an instance of PIL.Image from the given file.
    @param {String} dir_path - The directory containing the image file
    @param {String} image_file - The filename of the image file within dir_path
    @return {PIL.Image} An instance of the image file as a PIL Image, or None
        if the functionality is not available. This could be because PIL is not
        present, or because it can't process the given file type.
    """
    # Save ourselves the effort if PIL is not present, and return None now
    if not PIL_ENABLED:
        return None
    # Put together full path
    path = os.path.join(dir_path, image_file)
    # Try to read the image
    img = None
    try:
        img = Image.open(path)
    except IOError as exptn:
        print('Error loading image file %s: %s' % (path, exptn))
    # Return image or None
    return img

def count_bytes(self, filter_preds):
        '''Count bytes of all feature collections whose key satisfies one of
        the predicates in ``filter_preds``. The byte counts are binned
        by filter predicate.
        '''
        num_bytes = defaultdict(int)
        for hit in self._scan():
            for filter_pred in filter_preds:
                if filter_pred(did(hit['_id'])):
                    num_bytes[filter_pred] += self.fc_bytes(
                        hit['_source']['fc'])
        return num_bytes

def resolution_str(self):
        '''if set, get the value of resolution as "<n> <period>s", for example: "8 seconds"'''
        if self.resolution is None or isinstance(self.resolution, basestring):
            return self.resolution
        seconds = self.resolution / 1000.
        biggest = self._lookup[0]
        for entry in self._lookup:
            if seconds < entry[1]:
                break
            biggest = entry
        val = seconds / biggest[1]
        if val == int(val):
            val = int(val)
        return '%s %s' % (val, biggest[0])

