def setvar(parser, token):
    """ {% setvar <var_name> to <var_value> %} """

    try:
        setvar, var_name, to_, var_value = token.split_contents()
    except ValueError:
        raise template.TemplateSyntaxError('Invalid arguments for %r' % token.split_contents()[0])

